// MESH1 is little-endian. Its 48-byte preamble carries version and mesh counts, followed by
// 24-byte section descriptors {id, offset, byteLength, CRC32, recordCount, recordStride}.
// Sections begin on eight-byte boundaries so browser and Node loaders can expose typed views.
const MAGIC_BYTES = Uint8Array.of(0x4d, 0x45, 0x53, 0x48, 0x31, 0, 0, 0);
const PREAMBLE_BYTES = 48;
const SECTION_ENTRY_BYTES = 24;

export const MESH_ASSET_VERSION = 1;
export const NO_SLIT_COMPONENT = 0xffffffff;

export const MESH_SECTIONS = Object.freeze({
  positions: { id: 1, stride: 12, countFrom: 'vertexCount' },
  normals: { id: 2, stride: 12, countFrom: 'vertexCount' },
  uv0: { id: 3, stride: 8, countFrom: 'vertexCount' },
  indices: { id: 4, stride: 4, countFrom: 'indexCount' },
  triangleChartIds: { id: 5, stride: 4, countFrom: 'triangleCount' },
  charts: { id: 6, stride: 32, countFrom: 'chartCount' },
  seamPairs: { id: 7, stride: 56, countFrom: 'seamPairCount' },
  slitComponents: { id: 8, stride: 24, countFrom: 'slitComponentCount' },
});

const SECTION_NAMES_BY_ID = new Map(
  Object.entries(MESH_SECTIONS).map(([name, definition]) => [definition.id, name]),
);

export function parseMeshAsset(input, { verifyCrc = true } = {}) {
  const bytes = alignedByteView(input);
  requireCondition(bytes.byteLength >= PREAMBLE_BYTES, 'MESH1: truncated header');
  for (let index = 0; index < MAGIC_BYTES.length; index += 1) {
    requireCondition(bytes[index] === MAGIC_BYTES[index], 'MESH1: invalid magic');
  }
  const header = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  requireCondition(header.getUint32(8, true) === MESH_ASSET_VERSION, 'MESH1: unsupported version');
  const headerByteLength = header.getUint32(12, true);
  const sectionCount = header.getUint32(16, true);
  requireCondition(sectionCount === Object.keys(MESH_SECTIONS).length, 'MESH1: unexpected section count');
  requireCondition(
    headerByteLength === alignTo(PREAMBLE_BYTES + sectionCount * SECTION_ENTRY_BYTES, 8),
    'MESH1: invalid header length',
  );
  requireCondition(headerByteLength <= bytes.byteLength, 'MESH1: header overruns input');

  const counts = {
    vertexCount: header.getUint32(20, true),
    triangleCount: header.getUint32(24, true),
    chartCount: header.getUint32(28, true),
    seamPairCount: header.getUint32(32, true),
    directionalSideCount: header.getUint32(36, true),
    slitComponentCount: header.getUint32(40, true),
  };
  counts.indexCount = counts.triangleCount * 3;
  requireCondition(counts.directionalSideCount === counts.seamPairCount * 2, 'MESH1: side count mismatch');

  const sectionEntries = readSectionEntries(header, sectionCount, counts, headerByteLength, bytes.byteLength);
  const rawSections = {};
  for (const [name, entry] of Object.entries(sectionEntries)) {
    const sectionBytes = bytes.subarray(entry.byteOffset, entry.byteOffset + entry.byteLength);
    if (verifyCrc) {
      requireCondition(crc32(sectionBytes) === entry.crc32, `MESH1: CRC mismatch in ${name}`);
    }
    rawSections[name] = sectionBytes;
  }

  return {
    version: MESH_ASSET_VERSION,
    ...counts,
    positions: typedSection(Float32Array, rawSections.positions),
    normals: typedSection(Float32Array, rawSections.normals),
    uv0: typedSection(Float32Array, rawSections.uv0),
    indices: typedSection(Uint32Array, rawSections.indices),
    triangleChartIds: typedSection(Uint32Array, rawSections.triangleChartIds),
    charts: decodeCharts(rawSections.charts),
    seamPairs: decodeSeamPairs(rawSections.seamPairs),
    slitComponents: decodeSlitComponents(rawSections.slitComponents),
    rawSections,
    sectionEntries,
  };
}

export function crc32(bytes) {
  let value = 0xffffffff;
  for (const byte of bytes) value = CRC_TABLE[(value ^ byte) & 0xff] ^ (value >>> 8);
  return (value ^ 0xffffffff) >>> 0;
}

export function meshAssetHeaderLayout() {
  return {
    magicBytes: MAGIC_BYTES.slice(),
    preambleBytes: PREAMBLE_BYTES,
    sectionEntryBytes: SECTION_ENTRY_BYTES,
    headerBytes: alignTo(PREAMBLE_BYTES + Object.keys(MESH_SECTIONS).length * SECTION_ENTRY_BYTES, 8),
  };
}

function readSectionEntries(header, sectionCount, counts, headerByteLength, assetByteLength) {
  const entries = {};
  const ranges = [];
  for (let entryIndex = 0; entryIndex < sectionCount; entryIndex += 1) {
    const offset = PREAMBLE_BYTES + entryIndex * SECTION_ENTRY_BYTES;
    const id = header.getUint32(offset, true);
    const name = SECTION_NAMES_BY_ID.get(id);
    requireCondition(name && !entries[name], `MESH1: unknown or duplicate section ${id}`);
    const entry = {
      id,
      byteOffset: header.getUint32(offset + 4, true),
      byteLength: header.getUint32(offset + 8, true),
      crc32: header.getUint32(offset + 12, true),
      recordCount: header.getUint32(offset + 16, true),
      recordStride: header.getUint32(offset + 20, true),
    };
    const definition = MESH_SECTIONS[name];
    requireCondition(entry.recordStride === definition.stride, `MESH1: invalid ${name} stride`);
    requireCondition(entry.recordCount === counts[definition.countFrom], `MESH1: invalid ${name} count`);
    requireCondition(entry.byteLength === entry.recordCount * entry.recordStride, `MESH1: invalid ${name} length`);
    requireCondition(entry.byteOffset % 8 === 0, `MESH1: unaligned ${name} section`);
    requireCondition(entry.byteOffset >= headerByteLength, `MESH1: ${name} overlaps the header`);
    requireCondition(entry.byteOffset + entry.byteLength <= assetByteLength, `MESH1: ${name} overruns input`);
    entries[name] = entry;
    ranges.push([entry.byteOffset, entry.byteOffset + entry.byteLength, name]);
  }
  requireCondition(Object.keys(entries).length === Object.keys(MESH_SECTIONS).length, 'MESH1: missing section');
  ranges.sort((left, right) => left[0] - right[0]);
  for (let index = 1; index < ranges.length; index += 1) {
    requireCondition(ranges[index - 1][1] <= ranges[index][0], `MESH1: overlapping ${ranges[index][2]} section`);
  }
  return entries;
}

function decodeCharts(bytes) {
  const view = dataView(bytes);
  const records = [];
  for (let byteOffset = 0; byteOffset < bytes.byteLength; byteOffset += MESH_SECTIONS.charts.stride) {
    records.push({
      triangleCount: view.getUint32(byteOffset, true),
      uvBounds: [0, 1, 2, 3].map((index) => view.getFloat32(byteOffset + 8 + index * 4, true)),
      uvArea: view.getFloat64(byteOffset + 24, true),
    });
  }
  return records;
}

function decodeSeamPairs(bytes) {
  const view = dataView(bytes);
  const records = [];
  for (let byteOffset = 0; byteOffset < bytes.byteLength; byteOffset += MESH_SECTIONS.seamPairs.stride) {
    const side0 = {
      triangleIndex: view.getUint32(byteOffset, true),
      vertex0: view.getUint32(byteOffset + 8, true),
      vertex1: view.getUint32(byteOffset + 12, true),
      chartId: view.getUint32(byteOffset + 24, true),
      uvAltitude: view.getFloat32(byteOffset + 44, true),
    };
    const side1 = {
      triangleIndex: view.getUint32(byteOffset + 4, true),
      vertex0: view.getUint32(byteOffset + 16, true),
      vertex1: view.getUint32(byteOffset + 20, true),
      chartId: view.getUint32(byteOffset + 28, true),
      uvAltitude: view.getFloat32(byteOffset + 48, true),
    };
    records.push({
      sides: [side0, side1],
      slitComponentId: view.getUint32(byteOffset + 32, true),
      isSlit: Boolean(view.getUint32(byteOffset + 36, true) & 1),
      foldAngleRadians: view.getFloat32(byteOffset + 40, true),
      coincidenceError: view.getFloat32(byteOffset + 52, true),
    });
  }
  return records;
}

function decodeSlitComponents(bytes) {
  const view = dataView(bytes);
  const records = [];
  for (let byteOffset = 0; byteOffset < bytes.byteLength; byteOffset += MESH_SECTIONS.slitComponents.stride) {
    records.push({
      chartId: view.getUint32(byteOffset, true),
      edgeCount: view.getUint32(byteOffset + 4, true),
      maxBranchDegree: view.getUint32(byteOffset + 8, true),
      branchVertexCount: view.getUint32(byteOffset + 12, true),
      closedLoop: Boolean(view.getUint32(byteOffset + 16, true)),
    });
  }
  return records;
}

function typedSection(ArrayType, bytes) {
  return new ArrayType(bytes.buffer, bytes.byteOffset, bytes.byteLength / ArrayType.BYTES_PER_ELEMENT);
}

function dataView(bytes) {
  return new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
}

function alignedByteView(input) {
  requireCondition(ArrayBuffer.isView(input) || input instanceof ArrayBuffer, 'MESH1: expected binary input');
  const bytes = input instanceof ArrayBuffer
    ? new Uint8Array(input)
    : new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
  return bytes.byteOffset % 8 === 0 ? bytes : bytes.slice();
}

function alignTo(value, alignment) {
  return Math.ceil(value / alignment) * alignment;
}

function requireCondition(condition, message) {
  if (!condition) throw new Error(message);
}

const CRC_TABLE = Uint32Array.from({ length: 256 }, (_, index) => {
  let value = index;
  for (let bit = 0; bit < 8; bit += 1) value = (value >>> 1) ^ ((value & 1) ? 0xedb88320 : 0);
  return value >>> 0;
});

import { calculateCornerCensus, classifySlitComponents } from './mesh-components.mjs';
import { DisjointSets } from './union-find.mjs';

export const POSITION_PAIR_EPSILON = 1e-5;
const NO_COMPONENT = 0xffffffff;

export function buildChartSegmentation(uv0, indices) {
  validateMeshInputs(undefined, uv0, indices);
  const triangleCount = indices.length / 3;
  const sets = new DisjointSets(triangleCount);
  const edgeUses = new Map();
  let nonManifoldEdgeCount = 0;

  forEachTriangleEdge(indices, (triangleIndex, vertex0, vertex1) => {
    const key = indexEdgeKey(vertex0, vertex1, uv0.length / 2);
    const firstUse = edgeUses.get(key);
    if (!firstUse) {
      edgeUses.set(key, { triangleIndex, vertex0, vertex1, useCount: 1 });
      return;
    }
    if (!sameUvEdge(firstUse, vertex0, vertex1, uv0)) return;
    sets.union(firstUse.triangleIndex, triangleIndex);
    firstUse.useCount += 1;
    if (firstUse.useCount === 3) nonManifoldEdgeCount += 1;
  });

  const triangleChartIds = new Uint32Array(triangleCount);
  const rootToChart = new Map();
  for (let triangleIndex = 0; triangleIndex < triangleCount; triangleIndex += 1) {
    const root = sets.find(triangleIndex);
    if (!rootToChart.has(root)) rootToChart.set(root, rootToChart.size);
    triangleChartIds[triangleIndex] = rootToChart.get(root);
  }

  const charts = createChartStats(rootToChart.size);
  for (let triangleIndex = 0; triangleIndex < triangleCount; triangleIndex += 1) {
    accumulateChartTriangle(charts[triangleChartIds[triangleIndex]], triangleIndex, uv0, indices);
  }
  const boundarySides = [];
  for (const edge of edgeUses.values()) {
    if (edge.useCount !== 1) continue;
    boundarySides.push({
      triangleIndex: edge.triangleIndex,
      vertex0: edge.vertex0,
      vertex1: edge.vertex1,
      chartId: triangleChartIds[edge.triangleIndex],
    });
  }

  return { triangleChartIds, charts, boundarySides, nonManifoldEdgeCount };
}

export function extractSeamEdges(
  positions,
  uv0,
  indices,
  segmentation,
  { positionEpsilon = POSITION_PAIR_EPSILON } = {},
) {
  validateMeshInputs(positions, uv0, indices);
  if (!segmentation?.triangleChartIds || !segmentation?.boundarySides) {
    throw new Error('seams: chart segmentation with boundary sides is required');
  }
  if (!(positionEpsilon > 0)) throw new Error('seams: position epsilon must be positive');

  const edgeGroups = groupBoundarySides(positions, segmentation.boundarySides, positionEpsilon);
  const seamPairs = [];
  let unmatchedBoundaryCount = 0;
  let ambiguousBoundaryCount = 0;
  for (const sides of edgeGroups.values()) {
    if (sides.length === 1) {
      unmatchedBoundaryCount += 1;
      continue;
    }
    if (sides.length !== 2) {
      ambiguousBoundaryCount += sides.length;
      continue;
    }
    seamPairs.push(makeSeamPair(positions, uv0, indices, sides[0], sides[1], positionEpsilon));
  }
  if (unmatchedBoundaryCount || ambiguousBoundaryCount) {
    throw new Error(
      `seams: ${unmatchedBoundaryCount} unmatched and ${ambiguousBoundaryCount} ambiguous boundary sides`,
    );
  }

  const slitAnalysis = classifySlitComponents(seamPairs, positions, positionEpsilon);
  return {
    seamPairs,
    directionalSideCount: seamPairs.length * 2,
    slitComponents: slitAnalysis.components,
    endpointGroupedSlitComponentCount: slitAnalysis.endpointGroupedCount,
    endpointGroupStats: slitAnalysis.endpointGroupStats,
    chartLocalComponentStats: slitAnalysis.chartLocalStats,
    cornerCensus: calculateCornerCensus(
      positions,
      indices,
      segmentation.triangleChartIds,
      positionEpsilon,
    ),
    positionEpsilon,
  };
}

export function countSubTexelCharts(uv0, indices, triangleChartIds, chartCount, fieldSize) {
  validateMeshInputs(undefined, uv0, indices);
  if (triangleChartIds.length !== indices.length / 3) throw new Error('sub-texel: chart id count mismatch');
  if (!Number.isInteger(fieldSize) || fieldSize <= 0) throw new Error('sub-texel: invalid field size');
  const containsCenter = new Uint8Array(chartCount);
  let remaining = chartCount;
  for (let triangleIndex = 0; triangleIndex < triangleChartIds.length && remaining; triangleIndex += 1) {
    const chartId = triangleChartIds[triangleIndex];
    if (containsCenter[chartId]) continue;
    if (triangleContainsTexelCenter(uv0, indices, triangleIndex, fieldSize)) {
      containsCenter[chartId] = 1;
      remaining -= 1;
    }
  }
  const chartIds = [];
  for (let chartId = 0; chartId < chartCount; chartId += 1) {
    if (!containsCenter[chartId]) chartIds.push(chartId);
  }
  return chartIds;
}

function groupBoundarySides(positions, boundarySides, epsilon) {
  const groups = new Map();
  for (const side of boundarySides) {
    const endpoint0 = positionKey(positions, side.vertex0, epsilon);
    const endpoint1 = positionKey(positions, side.vertex1, epsilon);
    const key = endpoint0 < endpoint1 ? `${endpoint0}|${endpoint1}` : `${endpoint1}|${endpoint0}`;
    let group = groups.get(key);
    if (!group) groups.set(key, group = []);
    group.push(side);
  }
  return groups;
}

function makeSeamPair(positions, uv0, indices, side0, sourceSide1, epsilon) {
  const directDistance = pairedEndpointDistance(positions, side0, sourceSide1, false);
  const reversedDistance = pairedEndpointDistance(positions, side0, sourceSide1, true);
  const reverseSide1 = reversedDistance < directDistance;
  const coincidenceError = Math.min(directDistance, reversedDistance);
  if (coincidenceError > epsilon) {
    throw new Error(`seams: paired edges differ by ${coincidenceError}, above epsilon ${epsilon}`);
  }
  const side1 = reverseSide1
    ? { ...sourceSide1, vertex0: sourceSide1.vertex1, vertex1: sourceSide1.vertex0 }
    : { ...sourceSide1 };
  const pair = {
    sides: [
      { ...side0, uvAltitude: triangleUvAltitude(uv0, indices, side0) },
      { ...side1, uvAltitude: triangleUvAltitude(uv0, indices, side1) },
    ],
    foldAngleRadians: foldAngle(positions, indices, side0.triangleIndex, side1.triangleIndex),
    coincidenceError,
    slitComponentId: NO_COMPONENT,
  };
  pair.isSlit = pair.sides[0].chartId === pair.sides[1].chartId;
  return pair;
}

function createChartStats(chartCount) {
  return Array.from({ length: chartCount }, (_, id) => ({
    id,
    triangleCount: 0,
    uvBounds: [Infinity, Infinity, -Infinity, -Infinity],
    uvArea: 0,
  }));
}

function accumulateChartTriangle(chart, triangleIndex, uv0, indices) {
  const vertices = [indices[triangleIndex * 3], indices[triangleIndex * 3 + 1], indices[triangleIndex * 3 + 2]];
  const points = vertices.map((vertexIndex) => [uv0[vertexIndex * 2], uv0[vertexIndex * 2 + 1]]);
  chart.triangleCount += 1;
  for (const [u, v] of points) {
    chart.uvBounds[0] = Math.min(chart.uvBounds[0], u);
    chart.uvBounds[1] = Math.min(chart.uvBounds[1], v);
    chart.uvBounds[2] = Math.max(chart.uvBounds[2], u);
    chart.uvBounds[3] = Math.max(chart.uvBounds[3], v);
  }
  chart.uvArea += Math.abs(cross2(points[0], points[1], points[2])) * 0.5;
}

function triangleContainsTexelCenter(uv0, indices, triangleIndex, fieldSize) {
  const points = [0, 1, 2].map((corner) => {
    const vertexIndex = indices[triangleIndex * 3 + corner];
    return [uv0[vertexIndex * 2] * fieldSize, uv0[vertexIndex * 2 + 1] * fieldSize];
  });
  const denominator = cross2(points[0], points[1], points[2]);
  if (denominator === 0) return false;
  const minX = Math.max(0, Math.floor(Math.min(points[0][0], points[1][0], points[2][0])));
  const maxX = Math.min(fieldSize - 1, Math.ceil(Math.max(points[0][0], points[1][0], points[2][0])));
  const minY = Math.max(0, Math.floor(Math.min(points[0][1], points[1][1], points[2][1])));
  const maxY = Math.min(fieldSize - 1, Math.ceil(Math.max(points[0][1], points[1][1], points[2][1])));
  for (let y = minY; y <= maxY; y += 1) {
    for (let x = minX; x <= maxX; x += 1) {
      const point = [x + 0.5, y + 0.5];
      const a = cross2(point, points[1], points[2]) / denominator;
      const b = cross2(points[0], point, points[2]) / denominator;
      const c = 1 - a - b;
      if (a >= 0 && b >= 0 && c >= 0) return true;
    }
  }
  return false;
}

function triangleUvAltitude(uv0, indices, side) {
  const triangleVertices = indices.subarray(side.triangleIndex * 3, side.triangleIndex * 3 + 3);
  const opposite = triangleVertices.find((vertexIndex) => vertexIndex !== side.vertex0 && vertexIndex !== side.vertex1);
  if (opposite === undefined) throw new Error(`seams: triangle ${side.triangleIndex} has a degenerate edge`);
  const a = [uv0[side.vertex0 * 2], uv0[side.vertex0 * 2 + 1]];
  const b = [uv0[side.vertex1 * 2], uv0[side.vertex1 * 2 + 1]];
  const c = [uv0[opposite * 2], uv0[opposite * 2 + 1]];
  const edgeLength = Math.hypot(b[0] - a[0], b[1] - a[1]);
  if (!(edgeLength > 0)) throw new Error(`seams: triangle ${side.triangleIndex} has a zero-length UV edge`);
  return Math.abs(cross2(a, b, c)) / edgeLength;
}

function foldAngle(positions, indices, triangle0, triangle1) {
  const normal0 = triangleNormal(positions, indices, triangle0);
  const normal1 = triangleNormal(positions, indices, triangle1);
  const dot = Math.abs(normal0[0] * normal1[0] + normal0[1] * normal1[1] + normal0[2] * normal1[2]);
  return Math.acos(Math.max(-1, Math.min(1, dot)));
}

function triangleNormal(positions, indices, triangleIndex) {
  const a = indices[triangleIndex * 3];
  const b = indices[triangleIndex * 3 + 1];
  const c = indices[triangleIndex * 3 + 2];
  const ab = vectorBetween(positions, a, b);
  const ac = vectorBetween(positions, a, c);
  const normal = [
    ab[1] * ac[2] - ab[2] * ac[1],
    ab[2] * ac[0] - ab[0] * ac[2],
    ab[0] * ac[1] - ab[1] * ac[0],
  ];
  const length = Math.hypot(...normal);
  if (!(length > 0)) throw new Error(`seams: triangle ${triangleIndex} has zero world-space area`);
  return normal.map((value) => value / length);
}

function pairedEndpointDistance(positions, side0, side1, reverse) {
  const first = reverse ? side1.vertex1 : side1.vertex0;
  const second = reverse ? side1.vertex0 : side1.vertex1;
  return Math.max(
    endpointDistance(positions, side0.vertex0, first),
    endpointDistance(positions, side0.vertex1, second),
  );
}

function endpointDistance(positions, vertex0, vertex1) {
  return Math.hypot(...vectorBetween(positions, vertex0, vertex1));
}

function vectorBetween(positions, startVertex, endVertex) {
  return [0, 1, 2].map((axis) => positions[endVertex * 3 + axis] - positions[startVertex * 3 + axis]);
}

function positionKey(positions, vertexIndex, epsilon) {
  const offset = vertexIndex * 3;
  return `${Math.round(positions[offset] / epsilon)}_${Math.round(positions[offset + 1] / epsilon)}_${Math.round(positions[offset + 2] / epsilon)}`;
}

function sameUvEdge(firstUse, vertex0, vertex1, uv0) {
  return (
    sameUvVertex(firstUse.vertex0, vertex0, uv0) && sameUvVertex(firstUse.vertex1, vertex1, uv0)
  ) || (
    sameUvVertex(firstUse.vertex0, vertex1, uv0) && sameUvVertex(firstUse.vertex1, vertex0, uv0)
  );
}

function sameUvVertex(vertex0, vertex1, uv0) {
  return uv0[vertex0 * 2] === uv0[vertex1 * 2] && uv0[vertex0 * 2 + 1] === uv0[vertex1 * 2 + 1];
}

function cross2(a, b, c) {
  return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
}

function forEachTriangleEdge(indices, visit) {
  for (let triangleIndex = 0; triangleIndex < indices.length / 3; triangleIndex += 1) {
    const offset = triangleIndex * 3;
    visit(triangleIndex, indices[offset], indices[offset + 1]);
    visit(triangleIndex, indices[offset + 1], indices[offset + 2]);
    visit(triangleIndex, indices[offset + 2], indices[offset]);
  }
}

function indexEdgeKey(vertex0, vertex1, vertexCount) {
  const low = Math.min(vertex0, vertex1);
  return low * vertexCount + Math.max(vertex0, vertex1);
}

function validateMeshInputs(positions, uv0, indices) {
  if (!(uv0 instanceof Float32Array) || uv0.length === 0 || uv0.length % 2) {
    throw new Error('mesh: uv0 must be a non-empty Float32Array of pairs');
  }
  if (!(indices instanceof Uint32Array) || indices.length === 0 || indices.length % 3) {
    throw new Error('mesh: indices must be a non-empty Uint32Array of triangles');
  }
  if (positions !== undefined && (!(positions instanceof Float32Array) || positions.length / 3 !== uv0.length / 2)) {
    throw new Error('mesh: positions must match the UV vertex count');
  }
}

import { DisjointSets } from './union-find.mjs';

export function classifySlitComponents(seamPairs, positions, epsilon) {
  const slitPairIndices = [];
  for (let pairIndex = 0; pairIndex < seamPairs.length; pairIndex += 1) {
    if (seamPairs[pairIndex].isSlit) slitPairIndices.push(pairIndex);
  }

  const localGroups = connectedPairGroups(seamPairs, slitPairIndices, positions, epsilon, true);
  const globalGroups = connectedPairGroups(seamPairs, slitPairIndices, positions, epsilon, false);
  const components = localGroups.map((pairIndices, id) => {
    for (const pairIndex of pairIndices) seamPairs[pairIndex].slitComponentId = id;
    return describeGroup(id, pairIndices, seamPairs, positions, epsilon);
  });
  const globalDescriptions = globalGroups.map((pairIndices, id) => (
    describeGroup(id, pairIndices, seamPairs, positions, epsilon)
  ));

  return {
    components,
    endpointGroupedCount: globalGroups.length,
    chartLocalStats: summarizeGroups(components),
    endpointGroupStats: {
      ...summarizeGroups(globalDescriptions),
      multiChartGroupCount: globalDescriptions.filter((group) => group.chartIds.length > 1).length,
    },
  };
}

export function calculateCornerCensus(positions, indices, triangleChartIds, epsilon) {
  const chartsByPosition = new Map();
  for (let triangleIndex = 0; triangleIndex < triangleChartIds.length; triangleIndex += 1) {
    for (let corner = 0; corner < 3; corner += 1) {
      const key = positionKey(positions, indices[triangleIndex * 3 + corner], epsilon);
      let charts = chartsByPosition.get(key);
      if (!charts) chartsByPosition.set(key, charts = new Set());
      charts.add(triangleChartIds[triangleIndex]);
    }
  }
  const byChartCount = {};
  const angleSums = new Map();
  for (const [key, charts] of chartsByPosition) {
    byChartCount[charts.size] = (byChartCount[charts.size] ?? 0) + 1;
    if (charts.size >= 3) angleSums.set(key, 0);
  }
  for (let triangleIndex = 0; triangleIndex < triangleChartIds.length; triangleIndex += 1) {
    for (let corner = 0; corner < 3; corner += 1) {
      const vertexIndex = indices[triangleIndex * 3 + corner];
      const key = positionKey(positions, vertexIndex, epsilon);
      if (angleSums.has(key)) {
        angleSums.set(key, angleSums.get(key) + cornerAngle(positions, indices, triangleIndex, corner));
      }
    }
  }
  const angleDefects = { positive: 0, negative: 0, flat: 0 };
  for (const angleSum of angleSums.values()) {
    const defect = 2 * Math.PI - angleSum;
    if (defect > 0.05) angleDefects.positive += 1;
    else if (defect < -0.05) angleDefects.negative += 1;
    else angleDefects.flat += 1;
  }
  return { byChartCount, angleDefects };
}

function connectedPairGroups(seamPairs, pairIndices, positions, epsilon, chartLocal) {
  const sets = new DisjointSets(pairIndices.length);
  const endpointOwners = new Map();
  for (let slitIndex = 0; slitIndex < pairIndices.length; slitIndex += 1) {
    const pair = seamPairs[pairIndices[slitIndex]];
    const chartPrefix = chartLocal ? `${pair.sides[0].chartId}:` : '';
    for (const vertexIndex of [pair.sides[0].vertex0, pair.sides[0].vertex1]) {
      const key = chartPrefix + positionKey(positions, vertexIndex, epsilon);
      if (endpointOwners.has(key)) sets.union(slitIndex, endpointOwners.get(key));
      else endpointOwners.set(key, slitIndex);
    }
  }
  const rootToGroup = new Map();
  const groups = [];
  for (let slitIndex = 0; slitIndex < pairIndices.length; slitIndex += 1) {
    const root = sets.find(slitIndex);
    if (!rootToGroup.has(root)) {
      rootToGroup.set(root, rootToGroup.size);
      groups.push([]);
    }
    groups[rootToGroup.get(root)].push(pairIndices[slitIndex]);
  }
  return groups;
}

function describeGroup(id, pairIndices, seamPairs, positions, epsilon) {
  const endpointDegrees = new Map();
  const chartIds = new Set();
  for (const pairIndex of pairIndices) {
    const side = seamPairs[pairIndex].sides[0];
    chartIds.add(side.chartId);
    for (const vertexIndex of [side.vertex0, side.vertex1]) {
      const key = positionKey(positions, vertexIndex, epsilon);
      endpointDegrees.set(key, (endpointDegrees.get(key) ?? 0) + 1);
    }
  }
  const degrees = [...endpointDegrees.values()];
  return {
    id,
    chartId: chartIds.size === 1 ? [...chartIds][0] : undefined,
    chartIds: [...chartIds].sort((left, right) => left - right),
    edgeCount: pairIndices.length,
    maxBranchDegree: Math.max(...degrees),
    branchVertexCount: degrees.filter((degree) => degree > 2).length,
    closedLoop: degrees.every((degree) => degree === 2),
  };
}

function summarizeGroups(groups) {
  return {
    componentCount: groups.length,
    branchingComponentCount: groups.filter((group) => group.maxBranchDegree > 2).length,
    branchVertexCount: groups.reduce((sum, group) => sum + group.branchVertexCount, 0),
    closedLoopCount: groups.filter((group) => group.closedLoop).length,
  };
}

function cornerAngle(positions, indices, triangleIndex, corner) {
  const vertex = indices[triangleIndex * 3 + corner];
  const vector0 = vectorBetween(positions, vertex, indices[triangleIndex * 3 + ((corner + 1) % 3)]);
  const vector1 = vectorBetween(positions, vertex, indices[triangleIndex * 3 + ((corner + 2) % 3)]);
  const denominator = Math.hypot(...vector0) * Math.hypot(...vector1);
  if (!(denominator > 0)) throw new Error(`corners: triangle ${triangleIndex} is degenerate`);
  const dot = vector0[0] * vector1[0] + vector0[1] * vector1[1] + vector0[2] * vector1[2];
  return Math.acos(Math.max(-1, Math.min(1, dot / denominator)));
}

function vectorBetween(positions, startVertex, endVertex) {
  return [0, 1, 2].map((axis) => positions[endVertex * 3 + axis] - positions[startVertex * 3 + axis]);
}

function positionKey(positions, vertexIndex, epsilon) {
  const offset = vertexIndex * 3;
  return `${Math.round(positions[offset] / epsilon)}_${Math.round(positions[offset + 1] / epsilon)}_${Math.round(positions[offset + 2] / epsilon)}`;
}

export const SURFACE_WORLD_SIZE = 9.6;

export {
  buildChartSegmentation,
  countSubTexelCharts,
  extractSeamEdges,
} from './mesh-topology.mjs';

// Legacy anchor main.js:15294: downstream camera, audio, and oat units assume this exact frame.
export function normalizeGeometry(sourcePositions) {
  validateTriples(sourcePositions, 'positions');
  const sourceBounds = measureBounds(sourcePositions);
  const sourceExtents = boundsExtents(sourceBounds);
  const longestSourceExtent = Math.max(...sourceExtents);
  if (!(longestSourceExtent > 0)) throw new Error('positions: bounding box has no extent');

  const sourceCenter = [
    (sourceBounds.min[0] + sourceBounds.max[0]) * 0.5,
    (sourceBounds.min[1] + sourceBounds.max[1]) * 0.5,
    (sourceBounds.min[2] + sourceBounds.max[2]) * 0.5,
  ];
  const scaleFactor = SURFACE_WORLD_SIZE / longestSourceExtent;
  const positions = new Float32Array(sourcePositions.length);
  for (let offset = 0; offset < sourcePositions.length; offset += 3) {
    positions[offset] = (sourcePositions[offset] - sourceCenter[0]) * scaleFactor;
    positions[offset + 1] = (sourcePositions[offset + 1] - sourceCenter[1]) * scaleFactor;
    positions[offset + 2] = (sourcePositions[offset + 2] - sourceCenter[2]) * scaleFactor;
  }

  return {
    positions,
    sourceBounds,
    normalizedBounds: measureBounds(positions),
    sourceCenter,
    scaleFactor,
  };
}

export function measureBounds(positions) {
  validateTriples(positions, 'positions');
  const min = [Infinity, Infinity, Infinity];
  const max = [-Infinity, -Infinity, -Infinity];
  for (let offset = 0; offset < positions.length; offset += 3) {
    for (let axis = 0; axis < 3; axis += 1) {
      const value = positions[offset + axis];
      if (!Number.isFinite(value)) throw new Error(`positions: non-finite value at scalar ${offset + axis}`);
      min[axis] = Math.min(min[axis], value);
      max[axis] = Math.max(max[axis], value);
    }
  }
  return { min, max };
}

export function boundsExtents(bounds) {
  return bounds.max.map((maximum, axis) => maximum - bounds.min[axis]);
}

function validateTriples(values, name) {
  if (!ArrayBuffer.isView(values) || values.length === 0 || values.length % 3 !== 0) {
    throw new Error(`${name}: expected a non-empty typed array of xyz triples`);
  }
}

