function makeMask(chartId, rows) {
  const width = rows[0].length;
  const height = rows.length;
  const dilated = Uint8Array.from(rows.join(''), (value) => Number(value));
  return {
    chart: { id: chartId },
    width,
    height,
    dilatedCount: dilated.reduce((sum, value) => sum + value, 0),
    dilatedRows: maskIntervals(dilated, width, height),
    authoritativeRows: maskIntervals(dilated, width, height),
  };
}

function makePaddedMask(chartId) {
  const dilated = Uint8Array.from('111111111', Number);
  const authoritative = Uint8Array.from('000010000', Number);
  return {
    chart: { id: chartId },
    width: 3,
    height: 3,
    dilatedCount: 9,
    dilatedRows: maskIntervals(dilated, 3, 3),
    authoritativeRows: maskIntervals(authoritative, 3, 3),
  };
}

import { MAX_PACKING_DEMAND, atlasTarget } from './atlas-constants.mjs';
import { packMasks } from './mask-packer.mjs';
import { buildChartMasks } from './raster-masks.mjs';

const DESKTOP_WORLD_TEXEL_RATIO_LIMIT = 1.15;

export function repackAtlas(splitMesh, fieldSize, overrides = {}) {
  const target = atlasTarget(fieldSize, overrides);
  return repackAtlasWithTarget(splitMesh, target);
}

export function repackAtlasWithTarget(splitMesh, target) {
  const { fieldSize } = target;
  const raster = buildChartMasks(splitMesh, target);
  if (target.role === 'mobile' && raster.measuredDemandRatio > MAX_PACKING_DEMAND) {
    throw new Error(
      `repack: mobile demand ${(raster.measuredDemandRatio * 100).toFixed(2)}% exceeds `
      + `${(MAX_PACKING_DEMAND * 100).toFixed(0)}%; use the 1280 fallback decision`,
    );
  }
  const packing = packMasks(raster.masks, fieldSize);
  if (packing.occupiedCount !== raster.dilatedTexelDemand) {
    throw new Error('repack: packed masks overlap despite collision proof');
  }
  const uv1 = buildUv1(splitMesh, raster.masks, packing.placements, fieldSize);
  const chartTable = buildChartTable(raster, packing.placements, fieldSize);
  const clearance = proveClearance(raster.masks, packing.placements, fieldSize, target.gutterTexels);
  // M1 re-derives the audited legacy atlas occupancy (mesh-report.md); it is the density baseline.
  const legacyWorldAreaPerTexel = totalWorldArea(splitMesh) / (0.523679082 * fieldSize ** 2);
  const meanWorldTexelWidthRatio = Math.sqrt(raster.meanWorldAreaPerTexel / legacyWorldAreaPerTexel);
  if (target.role === 'desktop' && meanWorldTexelWidthRatio > DESKTOP_WORLD_TEXEL_RATIO_LIMIT) {
    throw new Error(`repack: desktop mean world texel width ratio ${meanWorldTexelWidthRatio} exceeds 1.15`);
  }
  return {
    fieldSize,
    target,
    uv1,
    chartTable,
    masks: raster.masks,
    placements: packing.placements,
    clearance,
    stats: {
      authoritativeTexelCount: raster.authoritativeTexelCount,
      dilatedTexelDemand: raster.dilatedTexelDemand,
      measuredDemandRatio: raster.measuredDemandRatio,
      achievedOccupancyRatio: packing.occupancyRatio,
      minChartUpscaleCount: raster.minChartUpscaleCount,
      meanWorldAreaPerTexel: raster.meanWorldAreaPerTexel,
      meanWorldTexelWidthRatio,
      densityScale: target.densityScale,
      parameterConversions: densityConversions(target.densityScale),
    },
  };
}

export function proveClearance(masks, placements, fieldSize, gutterTexels) {
  const authoritativeOwner = new Uint32Array(fieldSize * fieldSize);
  const dilatedOwner = new Uint32Array(fieldSize * fieldSize);
  for (let index = 0; index < masks.length; index += 1) {
    const mask = masks[index];
    const placement = placements[index];
    writeRows(mask.dilatedRows, placement, fieldSize, (texelIndex) => {
      if (dilatedOwner[texelIndex]) throw new Error('repack: two closed gutter dilations intersect');
      dilatedOwner[texelIndex] = mask.chart.id;
    });
    writeRows(mask.authoritativeRows, placement, fieldSize, (texelIndex, x, y) => {
      if (x < gutterTexels || y < gutterTexels || x >= fieldSize - gutterTexels || y >= fieldSize - gutterTexels) {
        throw new Error(`repack: chart ${mask.chart.id} violates the atlas border margin`);
      }
      if (authoritativeOwner[texelIndex]) throw new Error('repack: authoritative chart masks intersect');
      authoritativeOwner[texelIndex] = mask.chart.id;
    });
  }
  const minimumDistance = directChebyshevDistance(authoritativeOwner, fieldSize, gutterTexels * 2);
  if (minimumDistance < gutterTexels * 2 + 1) {
    throw new Error(`repack: chart distance ${minimumDistance} is below ${gutterTexels * 2 + 1}`);
  }
  return { authoritativeOwner, dilatedOwner, minimumChebyshevDistance: minimumDistance };
}

function buildUv1(splitMesh, masks, placements, fieldSize) {
  const uv1 = new Float32Array(splitMesh.uv0.length);
  const chartByVertex = new Uint32Array(splitMesh.positions.length / 3);
  for (let triangleIndex = 0; triangleIndex < splitMesh.triangleChartIds.length; triangleIndex += 1) {
    const chartId = splitMesh.triangleChartIds[triangleIndex];
    for (let corner = 0; corner < 3; corner += 1) chartByVertex[splitMesh.indices[triangleIndex * 3 + corner]] = chartId;
  }
  for (let vertex = 0; vertex < chartByVertex.length; vertex += 1) {
    const chartIndex = chartByVertex[vertex] - 1;
    const mask = masks[chartIndex];
    const placement = placements[chartIndex];
    uv1[vertex * 2] = splitMesh.uv0[vertex * 2] * mask.chartScale
      + (placement.x - mask.baseTexelX) / fieldSize;
    uv1[vertex * 2 + 1] = splitMesh.uv0[vertex * 2 + 1] * mask.chartScale
      + (placement.y - mask.baseTexelY) / fieldSize;
  }
  return uv1;
}

function buildChartTable(raster, placements, fieldSize) {
  return raster.masks.map((mask, index) => ({
    chartId: mask.chart.id,
    originalChartId: mask.chart.originalChartId,
    scale: mask.chartScale,
    translateUv: [
      (placements[index].x - mask.baseTexelX) / fieldSize,
      (placements[index].y - mask.baseTexelY) / fieldSize,
    ],
    authoritativeTexelCount: mask.authoritativeCount,
    worldAreaPerTexel: mask.worldAreaPerTexel,
    texelDensityFactor: mask.texelDensityFactor,
    minChartUpscaled: mask.minChartUpscaled,
  }));
}

function directChebyshevDistance(owner, fieldSize, searchRadius) {
  let minimum = Infinity;
  for (let y = 0; y < fieldSize; y += 1) {
    for (let x = 0; x < fieldSize; x += 1) {
      const chartId = owner[y * fieldSize + x];
      if (!chartId) continue;
      for (let dy = -searchRadius; dy <= searchRadius; dy += 1) {
        const otherY = y + dy;
        if (otherY < 0 || otherY >= fieldSize) continue;
        for (let dx = -searchRadius; dx <= searchRadius; dx += 1) {
          const distance = Math.max(Math.abs(dx), Math.abs(dy));
          if (!distance || distance >= minimum) continue;
          const otherX = x + dx;
          if (otherX < 0 || otherX >= fieldSize) continue;
          const otherChart = owner[otherY * fieldSize + otherX];
          if (otherChart && otherChart !== chartId) minimum = distance;
        }
      }
    }
  }
  return Number.isFinite(minimum) ? minimum : searchRadius + 1;
}

function writeRows(rows, placement, fieldSize, visit) {
  for (let localY = 0; localY < rows.length; localY += 1) {
    const y = placement.y + localY;
    for (const [start, end] of rows[localY]) {
      for (let localX = start; localX <= end; localX += 1) {
        const x = placement.x + localX;
        visit(y * fieldSize + x, x, y);
      }
    }
  }
}

function densityConversions(densityScale) {
  return Object.freeze({
    sensorDistance: densityScale,
    stepSize: densityScale,
    childOffset: densityScale,
    repelUvGroup: densityScale,
    crowdKernelRadius: densityScale,
    foodDepositSprite: 1,
    diffusionPerTexel: 1,
  });
}

function totalWorldArea(splitMesh) {
  return splitMesh.charts.reduce((sum, chart) => sum + chart.worldArea, 0);
}
import { MAX_KERNEL_FOOTPRINT } from '../src/shared/params.js';

// One direct sample may reach the declared radius and bilinear may consume the next texel.
export const DESKTOP_GUTTER_TEXELS = Math.max(
  ...Object.values(MAX_KERNEL_FOOTPRINT).map((kernel) => kernel.requiredGutterTexels),
);
export const MOBILE_GUTTER_TEXELS = 3;
export const MIN_CHART_TEXELS = 4;
export const MAX_FRAME_LIST_LENGTH = 4;
export const MAX_PACKING_DEMAND = 0.85;
export const MAX_SECTION_BYTES = 95 * 1024 * 1024;
export const ATLAS_SCHEMA_VERSION = 2;
export const GUTTER_RECORD_OFFSET = 2 ** 16;
export const WEIGHT_QUANTIZATION_SUM = 65_535;
export const BLOCK_TEXELS = 32;

export const DEFAULT_ATLAS_TARGETS = Object.freeze([
  Object.freeze({
    fieldSize: 1536,
    gutterTexels: DESKTOP_GUTTER_TEXELS,
    directTapClampTexels: DESKTOP_GUTTER_TEXELS - 1,
    // Post-split conservative demand is 98.12% at s=1. The explicit s=.9 lever measures
    // 84.18% and changes regular-chart world texel width by 11.1%, inside M2's ~15% gate.
    densityScale: 0.9,
    role: 'desktop',
  }),
  Object.freeze({
    fieldSize: 1024,
    gutterTexels: MOBILE_GUTTER_TEXELS,
    directTapClampTexels: MOBILE_GUTTER_TEXELS - 1,
    // Post-split conservative demand is 92.88% at s=.9. The measured s=.83 lever packs at
    // 83.43%, satisfying the preset <=85% combined-lever policy without moving to 1280.
    densityScale: 0.83,
    role: 'mobile',
  }),
]);

export function atlasTarget(fieldSize, overrides = {}) {
  const baseline = DEFAULT_ATLAS_TARGETS.find((target) => target.fieldSize === fieldSize);
  if (!baseline) throw new RangeError(`atlas: unsupported target ${fieldSize}`);
  const target = { ...baseline, ...overrides, fieldSize };
  if (!Number.isInteger(target.gutterTexels) || target.gutterTexels < 1) {
    throw new RangeError('atlas: gutter must be a positive integer');
  }
  if (!(target.densityScale > 0 && target.densityScale <= 1)) {
    throw new RangeError('atlas: density scale must be in (0, 1]');
  }
  return target;
}
import { GUTTER_RECORD_OFFSET } from './atlas-constants.mjs';
import { directionalFrame, triangleJacobian } from './seams.mjs';
import { buildDonorStencil, quantizeNonnegativeWeights } from './stencils.mjs';
import {
  buildSurfaceTopology,
  closestPointOnSegment,
  walkSurfaceOffset,
} from './surface-walk.mjs';

const NO_TRIANGLE = 0xffffffff;
const STENCIL_CLASSES = Object.freeze({ 'exact-bilinear': 0, 'nonnegative-moment': 1, degraded: 2 });

export function rasterizeAtlas(splitMesh, repack) {
  const { fieldSize } = repack;
  const texelCount = fieldSize ** 2;
  const authoritativeOwner = repack.clearance.authoritativeOwner;
  const ownership = authoritativeOwner.slice();
  const triangleMap = new Uint32Array(texelCount).fill(NO_TRIANGLE);
  const worldPos = new Float32Array(texelCount * 3);
  const tangentFrame = new Float32Array(texelCount * 6);
  writeAuthoritativeMaps(splitMesh, repack, triangleMap, worldPos, tangentFrame);

  const boundary = buildBoundaryEdges(splitMesh, repack.uv1);
  const topology = buildSurfaceTopology(splitMesh);
  const gutterCount = repack.masks.reduce((sum, mask) => sum + mask.dilatedCount - mask.authoritativeCount, 0);
  const gutterCoords = new Uint32Array(gutterCount);
  const tapIndices = new Uint32Array(gutterCount * 4);
  const weights = new Float32Array(gutterCount * 4);
  const quantizedWeights = new Uint16Array(gutterCount * 4);
  const stencilClass = new Uint8Array(gutterCount);
  const walkTriangles = new Uint32Array(gutterCount);
  const walkHopCounts = new Uint16Array(gutterCount);
  const walkChartCrossings = new Uint16Array(gutterCount);
  const census = { exactBilinear: 0, nonnegativeMoment: 0, degraded: 0, signedDegraded: 0, maxPositionErrorTexels: 0, degradedTexels: [] };
  let recordIndex = 0;

  for (let chartIndex = 0; chartIndex < repack.masks.length; chartIndex += 1) {
    const mask = repack.masks[chartIndex];
    const placement = repack.placements[chartIndex];
    const nearest = assignNearestBoundary(mask, placement, boundary.byChart[mask.chart.id], fieldSize, repack.target.gutterTexels);
    for (let localY = 0; localY < mask.height; localY += 1) {
      for (let localX = 0; localX < mask.width; localX += 1) {
        const localIndex = localY * mask.width + localX;
        if (!mask.dilated[localIndex] || mask.authoritative[localIndex]) continue;
        const descriptor = boundary.edges[nearest.edgeIds[localIndex]];
        if (!descriptor) throw new Error(`raster: chart ${mask.chart.id} has an unresolved gutter texel`);
        const x = placement.x + localX; const y = placement.y + localY;
        const texelIndex = y * fieldSize + x;
        const edgeFraction = nearest.edgeFractions[localIndex];
        const boundaryUvPos = lerp2(descriptor.sourceUv0, descriptor.sourceUv1, edgeFraction);
        const gutterUvPos = [(x + 0.5) / fieldSize, (y + 0.5) / fieldSize];
        const endpoint = walkSurfaceOffset({
          mesh: splitMesh,
          uv1: repack.uv1,
          topology,
          sourceSide: descriptor.source,
          destinationSide: descriptor.destination,
          boundaryUvPos,
          edgeFraction,
          offsetUv: subtract2(gutterUvPos, boundaryUvPos),
        });
        const destinationChart = splitMesh.triangleChartIds[endpoint.triangleIndex];
        let stencil;
        try {
          stencil = buildDonorStencil(endpoint.uvPos, destinationChart, authoritativeOwner, fieldSize);
        } catch (error) {
          throw new Error(
            `raster: donor failed at ${x},${y}; edge=${descriptor.id}; pair=${descriptor.pairIndex}; `
            + `sourceChart=${mask.chart.id}; destinationChart=${destinationChart}; `
            + `triangle=${endpoint.triangleIndex}; endpointUv=${endpoint.uvPos.join(',')}; `
            + `hops=${endpoint.triangleHopCount}`,
            { cause: error },
          );
        }
        gutterCoords[recordIndex] = texelIndex;
        tapIndices.set(stencil.tapIndices, recordIndex * 4);
        weights.set(stencil.weights, recordIndex * 4);
        stencilClass[recordIndex] = STENCIL_CLASSES[stencil.stencilClass];
        walkTriangles[recordIndex] = endpoint.triangleIndex;
        walkHopCounts[recordIndex] = Math.min(0xffff, endpoint.triangleHopCount);
        walkChartCrossings[recordIndex] = Math.min(0xffff, endpoint.chartCrossingCount);
        ownership[texelIndex] = recordIndex + GUTTER_RECORD_OFFSET;
        census.maxPositionErrorTexels = Math.max(census.maxPositionErrorTexels, stencil.positionErrorTexels);
        census[stencil.stencilClass === 'exact-bilinear' ? 'exactBilinear' : stencil.stencilClass === 'nonnegative-moment' ? 'nonnegativeMoment' : 'degraded'] += 1;
        if (stencil.stencilClass === 'degraded') census.degradedTexels.push(texelIndex);
        if (stencil.hasNegativeWeight) census.signedDegraded += 1;
        else quantizedWeights.set(quantizeNonnegativeWeights(stencil.weights), recordIndex * 4);
        writeGatheredMap(recordIndex, texelIndex, tapIndices, weights, worldPos, tangentFrame);
        recordIndex += 1;
      }
    }
  }
  if (recordIndex !== gutterCount) throw new Error(`raster: expected ${gutterCount} gutters, wrote ${recordIndex}`);
  return {
    ownership,
    authoritativeOwner,
    triangleMap,
    worldPos,
    tangentFrame,
    gutter: {
      coords: gutterCoords,
      tapIndices,
      weights,
      quantizedWeights: census.signedDegraded ? null : quantizedWeights,
      partialQuantizedWeights: quantizedWeights,
      stencilClass,
      walkTriangles,
      walkHopCounts,
      walkChartCrossings,
      recordCount: gutterCount,
      deadCount: 0,
      deploymentBlocked: census.signedDegraded > 0,
      census,
    },
    boundaryEdges: boundary.edges,
    surfaceTopology: topology,
  };
}

function writeAuthoritativeMaps(mesh, repack, triangleMap, worldPos, tangentFrame) {
  const tangentCache = new Float32Array(mesh.triangleChartIds.length * 6);
  const tangentReady = new Uint8Array(mesh.triangleChartIds.length);
  for (let chartIndex = 0; chartIndex < repack.masks.length; chartIndex += 1) {
    const mask = repack.masks[chartIndex]; const placement = repack.placements[chartIndex];
    for (let localY = 0; localY < mask.height; localY += 1) {
      for (let localX = 0; localX < mask.width; localX += 1) {
        const localIndex = localY * mask.width + localX;
        if (!mask.authoritative[localIndex]) continue;
        const triangleIndex = mask.triangleRefs[localIndex];
        if (triangleIndex < 0) throw new Error('raster: authoritative texel has no triangle');
        const x = placement.x + localX; const y = placement.y + localY;
        const texelIndex = y * repack.fieldSize + x;
        triangleMap[texelIndex] = triangleIndex;
        const barycentric = uvBarycentric(mesh, repack.uv1, triangleIndex, [(x + 0.5) / repack.fieldSize, (y + 0.5) / repack.fieldSize]);
        interpolateTriangle(mesh.positions, mesh.indices, triangleIndex, barycentric, worldPos, texelIndex * 3, 3);
        if (!tangentReady[triangleIndex]) {
          const jacobian = triangleJacobian(mesh, repack.uv1, triangleIndex);
          tangentCache.set([...normalize3(jacobian.dU), ...normalize3(jacobian.dV)], triangleIndex * 6);
          tangentReady[triangleIndex] = 1;
        }
        tangentFrame.set(tangentCache.subarray(triangleIndex * 6, triangleIndex * 6 + 6), texelIndex * 6);
      }
    }
  }
}

function buildBoundaryEdges(mesh, uv1) {
  const edges = [null];
  const byChart = Array.from({ length: mesh.charts.length + 1 }, () => []);
  mesh.seamPairs.forEach((pair, pairIndex) => {
    for (let direction = 0; direction < 2; direction += 1) {
      const source = pair.sides[direction]; const destination = pair.sides[1 - direction];
      const id = edges.length;
      const edge = {
        id,
        frameId: pairIndex * 2 + direction + 1,
        pairIndex,
        direction,
        source,
        destination,
        sourceUv0: vertexUv(uv1, source.vertex0),
        sourceUv1: vertexUv(uv1, source.vertex1),
      };
      edge.entryMatrix = directionalFrame(mesh, uv1, pair, pairIndex, direction, 1).matrix;
      edge.destinationUv = [vertexUv(uv1, destination.vertex0), vertexUv(uv1, destination.vertex1)];
      edge.destinationTriangleUv = [...mesh.indices.subarray(destination.triangleIndex * 3, destination.triangleIndex * 3 + 3)]
        .map((vertex) => ({ vertex, uv: vertexUv(uv1, vertex) }));
      edges.push(edge); byChart[source.chartId].push(edge);
    }
  });
  return { edges, byChart };
}

function assignNearestBoundary(mask, placement, edges, fieldSize, gutterTexels) {
  const edgeIds = new Uint32Array(mask.authoritative.length);
  const edgeFractions = new Float32Array(mask.authoritative.length);
  const distances = new Float32Array(mask.authoritative.length).fill(Infinity);
  const alignments = new Float32Array(mask.authoritative.length).fill(-Infinity);
  for (const edge of edges) {
    const start = edge.sourceUv0.map((value) => value * fieldSize);
    const end = edge.sourceUv1.map((value) => value * fieldSize);
    const radius = gutterTexels + 2;
    const minX = Math.max(placement.x, Math.floor(Math.min(start[0], end[0]) - radius));
    const maxX = Math.min(placement.x + mask.width - 1, Math.ceil(Math.max(start[0], end[0]) + radius));
    const minY = Math.max(placement.y, Math.floor(Math.min(start[1], end[1]) - radius));
    const maxY = Math.min(placement.y + mask.height - 1, Math.ceil(Math.max(start[1], end[1]) + radius));
    for (let y = minY; y <= maxY; y += 1) for (let x = minX; x <= maxX; x += 1) {
      const localIndex = (y - placement.y) * mask.width + x - placement.x;
      if (!mask.dilated[localIndex] || mask.authoritative[localIndex]) continue;
      const closest = closestPointOnSegment([x + 0.5, y + 0.5], start, end);
      const offset = subtract2([x + 0.5, y + 0.5], closest.point);
      const alignment = (closest.t <= 1e-7 || closest.t >= 1 - 1e-7)
        ? entryConeScore(edge, closest.t, offset) : 0;
      const better = closest.distanceSquared < distances[localIndex] - 1e-7
        || (Math.abs(closest.distanceSquared - distances[localIndex]) <= 1e-7 && (
