  return uv0[vertex0 * 2] === uv0[vertex1 * 2] && uv0[vertex0 * 2 + 1] === uv0[vertex1 * 2 + 1];
}

function cross2(a, b, c) {
  return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
}

