  const roots = [...new Set(pairRows.flatMap((_, index) => [sets.find(index * 2), sets.find(index * 2 + 1)]))]
    .sort((left, right) => left - right);
  const labelByRoot = new Map(roots.map((root, label) => [root, label]));
  return pairRows.flatMap((_, index) => [labelByRoot.get(sets.find(index * 2)), labelByRoot.get(sets.find(index * 2 + 1))]);
}

function decomposePhysicalPaths(pairRows, positions) {
  const endpoints = pairRows.map(({ pair }) => [
    positionKey(positions, pair.sides[0].vertex0),
    positionKey(positions, pair.sides[0].vertex1),
  ]);
  const incident = new Map();
  endpoints.forEach(([key0, key1], rowIndex) => {
    for (const key of [key0, key1]) {
      let rows = incident.get(key);
      if (!rows) incident.set(key, rows = []);
      rows.push(rowIndex);
    }
  });
  const unused = new Set(pairRows.map((_, index) => index));
  const paths = [];
  const starts = [...incident].filter(([, rows]) => rows.length !== 2).sort(([left], [right]) => left.localeCompare(right));
  for (const [startKey, rows] of starts) {
    for (const firstRow of [...rows].sort((left, right) => pairRows[left].pairIndex - pairRows[right].pairIndex)) {
// Directional frame layout (16 f32, record zero reserved):
//   0..3  srcRef.xy, dstRef.xy
//   4..7  M columns (m00,m10), (m01,m11)
//   8..11 srcChart, dstChart, sourcePairIndex, direction
//   12..15 foldRadians, anisotropy, sourceLengthTexels, diagnostic polar angle
// Frames are size-specific uv1 transport data for the runtime agent resolver. Gutter fill never
// consumes this table; its donor endpoint comes from the exact surface walk.
export const FRAME_FLOATS = 16;

export function buildDirectionalFrames(splitMesh, repack) {
  const frameCount = splitMesh.seamPairs.length * 2;
  const frameData = new Float32Array((frameCount + 1) * FRAME_FLOATS);
  const frames = [];
  for (let pairIndex = 0; pairIndex < splitMesh.seamPairs.length; pairIndex += 1) {
    const pair = splitMesh.seamPairs[pairIndex];
    for (let direction = 0; direction < 2; direction += 1) {
      const frameId = pairIndex * 2 + direction + 1;
      const frame = directionalFrame(splitMesh, repack.uv1, pair, pairIndex, direction, repack.fieldSize);
      packFrame(frameData, frameId, frame);
      frames.push({ id: frameId, ...frame });
    }
  }
  return { frameData, frames, frameCount, frameStrideFloats: FRAME_FLOATS };
}

export function directionalFrame(mesh, uv1, pair, pairIndex, direction, fieldSize) {
  const source = pair.sides[direction];
  const destination = pair.sides[1 - direction];
  const sourceJacobian = triangleJacobian(mesh, uv1, source.triangleIndex);
  const destinationJacobian = triangleJacobian(mesh, uv1, destination.triangleIndex);
  const hinge = hingeRotation(mesh, source, destination);
  const unfoldedSourceJacobian = {
    dU: rotateVector(sourceJacobian.dU, hinge.axis, hinge.angleRadians),
    dV: rotateVector(sourceJacobian.dV, hinge.axis, hinge.angleRadians),
  };
  const matrix = projectJacobian(destinationJacobian, unfoldedSourceJacobian);
  const legacyMatrix = projectJacobian(destinationJacobian, sourceJacobian);
  const srcRef = vertexUv(uv1, source.vertex0);
  const dstRef = vertexUv(uv1, destination.vertex0);
  const sourceEdge = subtract2(vertexUv(uv1, source.vertex1), srcRef);
  const mappedEdge = applyMatrix(matrix, sourceEdge);
  const destinationEdge = subtract2(vertexUv(uv1, destination.vertex1), dstRef);
  if (distance2(mappedEdge, destinationEdge) * fieldSize > 0.25 + 1e-4) {
    throw new Error(`seams: frame ${pairIndex}/${direction} misses its shared edge`);
  }
  return {
    srcRef,
    dstRef,
    matrix,
    legacyMatrix,
    sourceChart: source.chartId,
    destinationChart: destination.chartId,
    sourcePairIndex: pair.sourcePairIndex,
    pairIndex,
    direction,
    foldAngleRadians: pair.foldAngleRadians,
    signedHingeRadians: hinge.angleRadians,
    anisotropy: matrixAnisotropy(matrix),
    sourceLengthTexels: Math.hypot(...sourceEdge) * fieldSize,
    diagnosticPolarAngle: Math.atan2(matrix.m10, matrix.m00),
  };
}

export function applyFrame(frame, uvPos) {
  const offset = subtract2(uvPos, frame.srcRef);
  const mapped = applyMatrix(frame.matrix, offset);
  return [mapped[0] + frame.dstRef[0], mapped[1] + frame.dstRef[1]];
}

export function transportHeading(frame, uvDirection) {
  const mapped = applyMatrix(frame.matrix, uvDirection);
  const length = Math.hypot(...mapped);
  if (!(length > 0)) throw new Error('seams: affine collapsed a heading');
  return mapped.map((value) => value / length);
}

export function triangleJacobian(mesh, uv1, triangleIndex) {
  const vertices = [...mesh.indices.subarray(triangleIndex * 3, triangleIndex * 3 + 3)];
  const [vertexA, vertexB, vertexC] = vertices;
  const edge1 = worldVector(mesh.positions, vertexA, vertexB);
  const edge2 = worldVector(mesh.positions, vertexA, vertexC);
  const uvA = vertexUv(uv1, vertexA);
  const uvB = vertexUv(uv1, vertexB);
  const uvC = vertexUv(uv1, vertexC);
  const d1 = subtract2(uvB, uvA);
  const d2 = subtract2(uvC, uvA);
  const determinant = d1[0] * d2[1] - d1[1] * d2[0];
  if (Math.abs(determinant) < 1e-20) throw new Error(`seams: triangle ${triangleIndex} has singular uv1`);
  return {
    dU: combine3(edge1, d2[1] / determinant, edge2, -d1[1] / determinant),
    dV: combine3(edge2, d1[0] / determinant, edge1, -d2[0] / determinant),
  };
}

export function projectJacobian(destination, source) {
  const a00 = dot3(destination.dU, source.dU);
  const a01 = dot3(destination.dU, source.dV);
  const a10 = dot3(destination.dV, source.dU);
  const a11 = dot3(destination.dV, source.dV);
  const g00 = dot3(destination.dU, destination.dU);
  const g01 = dot3(destination.dU, destination.dV);
  const g11 = dot3(destination.dV, destination.dV);
  const determinant = g00 * g11 - g01 * g01;
  if (Math.abs(determinant) < 1e-20) throw new Error('seams: destination Jacobian is singular');
  const inverse = 1 / determinant;
  const i00 = g11 * inverse; const i01 = -g01 * inverse;
  const i10 = -g01 * inverse; const i11 = g00 * inverse;
  return {
    m00: i00 * a00 + i01 * a10,
    m01: i00 * a01 + i01 * a11,
    m10: i10 * a00 + i11 * a10,
    m11: i10 * a01 + i11 * a11,
  };
}

function hingeRotation(mesh, source, destination) {
  const axis = normalize3(worldVector(mesh.positions, source.vertex0, source.vertex1));
  const midpoint = [0, 1, 2].map((coordinate) => (
    mesh.positions[source.vertex0 * 3 + coordinate] + mesh.positions[source.vertex1 * 3 + coordinate]
  ) * 0.5);
  const sourceOutward = triangleInward(mesh, source.triangleIndex, midpoint, axis).map((value) => -value);
  const destinationInward = triangleInward(mesh, destination.triangleIndex, midpoint, axis);
  return {
    axis,
    angleRadians: Math.atan2(dot3(axis, cross3(sourceOutward, destinationInward)), dot3(sourceOutward, destinationInward)),
  };
}

function triangleInward(mesh, triangleIndex, edgeMidpoint, edgeAxis) {
  const vertices = [...mesh.indices.subarray(triangleIndex * 3, triangleIndex * 3 + 3)];
  const centroid = [0, 1, 2].map((coordinate) => vertices.reduce((sum, vertex) => (
    sum + mesh.positions[vertex * 3 + coordinate]
  ), 0) / 3);
  const towardCentroid = centroid.map((value, coordinate) => value - edgeMidpoint[coordinate]);
  const alongEdge = dot3(towardCentroid, edgeAxis);
  return normalize3(towardCentroid.map((value, coordinate) => value - edgeAxis[coordinate] * alongEdge));
}

function rotateVector(vector, axis, angle) {
  const cosine = Math.cos(angle); const sine = Math.sin(angle);
  const cross = cross3(axis, vector); const along = dot3(axis, vector) * (1 - cosine);
  return [0, 1, 2].map((index) => vector[index] * cosine + cross[index] * sine + axis[index] * along);
}

function matrixAnisotropy(matrix) {
  const trace = matrix.m00 ** 2 + matrix.m01 ** 2 + matrix.m10 ** 2 + matrix.m11 ** 2;
  const determinantSquared = (matrix.m00 * matrix.m11 - matrix.m01 * matrix.m10) ** 2;
  const discriminant = Math.sqrt(Math.max(0, trace ** 2 - 4 * determinantSquared));
  const largest = Math.sqrt(Math.max(0, (trace + discriminant) * 0.5));
  const smallest = Math.sqrt(Math.max(0, (trace - discriminant) * 0.5));
  return smallest > 1e-12 ? largest / smallest : Infinity;
}

function packFrame(frameData, frameId, frame) {
  const offset = frameId * FRAME_FLOATS;
  frameData.set([
    ...frame.srcRef, ...frame.dstRef,
    frame.matrix.m00, frame.matrix.m10, frame.matrix.m01, frame.matrix.m11,
    frame.sourceChart, frame.destinationChart, frame.sourcePairIndex, frame.direction,
    frame.foldAngleRadians, frame.anisotropy, frame.sourceLengthTexels, frame.diagnosticPolarAngle,
  ], offset);
}

function applyMatrix(matrix, vector) {
  return [matrix.m00 * vector[0] + matrix.m01 * vector[1], matrix.m10 * vector[0] + matrix.m11 * vector[1]];
}

function vertexUv(uv, vertex) { return [uv[vertex * 2], uv[vertex * 2 + 1]]; }
function subtract2(a, b) { return [a[0] - b[0], a[1] - b[1]]; }
function distance2(a, b) { return Math.hypot(a[0] - b[0], a[1] - b[1]); }
function worldVector(positions, start, end) { return [0, 1, 2].map((axis) => positions[end * 3 + axis] - positions[start * 3 + axis]); }
function combine3(a, aScale, b, bScale) { return [0, 1, 2].map((axis) => a[axis] * aScale + b[axis] * bScale); }
function cross3(a, b) { return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]; }
function dot3(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
function normalize3(value) { const length = Math.hypot(...value); return value.map((axis) => axis / length); }
import { BLOCK_TEXELS } from './atlas-constants.mjs';

export function buildBlockGraph(splitMesh, repack, raster, blockTexels = BLOCK_TEXELS) {
  const blocksPerAxis = Math.ceil(repack.fieldSize / blockTexels);
  const blockCount = blocksPerAxis ** 2;
  const nodeByChartBlock = new Map();
  const nodes = [];
  for (let texelIndex = 0; texelIndex < raster.authoritativeOwner.length; texelIndex += 1) {
    const chartId = raster.authoritativeOwner[texelIndex];
    if (!chartId) continue;
    const x = texelIndex % repack.fieldSize; const y = Math.floor(texelIndex / repack.fieldSize);
    const blockX = Math.floor(x / blockTexels); const blockY = Math.floor(y / blockTexels);
    const blockIndex = blockY * blocksPerAxis + blockX;
    const key = chartId * blockCount + blockIndex;
    let nodeIndex = nodeByChartBlock.get(key);
    if (nodeIndex === undefined) {
      nodeIndex = nodes.length;
      nodeByChartBlock.set(key, nodeIndex);
      nodes.push({ chartId, blockX, blockY, worldSum: [0, 0, 0], texelCount: 0 });
    }
    const node = nodes[nodeIndex];
    for (let axis = 0; axis < 3; axis += 1) node.worldSum[axis] += raster.worldPos[texelIndex * 3 + axis];
    node.texelCount += 1;
  }
  for (const node of nodes) node.worldCenter = node.worldSum.map((value) => value / node.texelCount);

  const edges = Array.from({ length: nodes.length }, () => new Map());
  nodes.forEach((node, nodeIndex) => {
    for (const [dx, dy] of [[1, 0], [0, 1]]) {
      const targetX = node.blockX + dx; const targetY = node.blockY + dy;
      if (targetX >= blocksPerAxis || targetY >= blocksPerAxis) continue;
      const targetKey = node.chartId * blockCount + targetY * blocksPerAxis + targetX;
      const targetIndex = nodeByChartBlock.get(targetKey);
      if (targetIndex !== undefined) connect(edges, nodes, nodeIndex, targetIndex, distance3(nodes[nodeIndex].worldCenter, nodes[targetIndex].worldCenter));
    }
  });
  for (const pair of splitMesh.seamPairs) {
    const nodeIndices = pair.sides.map((side) => nodeForSide(side, repack, nodeByChartBlock, blocksPerAxis, blockCount, blockTexels));
    if (nodeIndices.some((index) => index === undefined) || nodeIndices[0] === nodeIndices[1]) continue;
    const midpoint = [0, 1, 2].map((axis) => (
      splitMesh.positions[pair.sides[0].vertex0 * 3 + axis] + splitMesh.positions[pair.sides[0].vertex1 * 3 + axis]
    ) * 0.5);
    const weight = distance3(nodes[nodeIndices[0]].worldCenter, midpoint) + distance3(midpoint, nodes[nodeIndices[1]].worldCenter);
    connect(edges, nodes, nodeIndices[0], nodeIndices[1], weight);
  }
  return encodeGraph(nodes, edges, blocksPerAxis, blockTexels);
}

export function dijkstraBlockGraph(graph, sourceNode) {
  const distance = new Float64Array(graph.nodeCount).fill(Infinity);
  const visited = new Uint8Array(graph.nodeCount);
  distance[sourceNode] = 0;
  for (let iteration = 0; iteration < graph.nodeCount; iteration += 1) {
    let node = -1; let best = Infinity;
    for (let candidate = 0; candidate < graph.nodeCount; candidate += 1) {
      if (!visited[candidate] && distance[candidate] < best) { best = distance[candidate]; node = candidate; }
    }
    if (node < 0) break;
    visited[node] = 1;
    for (let edge = graph.offsets[node]; edge < graph.offsets[node + 1]; edge += 1) {
      const target = graph.targets[edge];
      distance[target] = Math.min(distance[target], distance[node] + graph.weights[edge]);
    }
  }
  return distance;
}

function nodeForSide(side, repack, nodeByChartBlock, blocksPerAxis, blockCount, blockTexels) {
  const u = (repack.uv1[side.vertex0 * 2] + repack.uv1[side.vertex1 * 2]) * 0.5;
  const v = (repack.uv1[side.vertex0 * 2 + 1] + repack.uv1[side.vertex1 * 2 + 1]) * 0.5;
  const blockX = clamp(Math.floor(u * repack.fieldSize / blockTexels), 0, blocksPerAxis - 1);
  const blockY = clamp(Math.floor(v * repack.fieldSize / blockTexels), 0, blocksPerAxis - 1);
  const direct = nodeByChartBlock.get(side.chartId * blockCount + blockY * blocksPerAxis + blockX);
  if (direct !== undefined) return direct;
  for (let radius = 1; radius < blocksPerAxis; radius += 1) {
    for (let y = Math.max(0, blockY - radius); y <= Math.min(blocksPerAxis - 1, blockY + radius); y += 1) {
      for (let x = Math.max(0, blockX - radius); x <= Math.min(blocksPerAxis - 1, blockX + radius); x += 1) {
        if (Math.max(Math.abs(x - blockX), Math.abs(y - blockY)) !== radius) continue;
        const candidate = nodeByChartBlock.get(side.chartId * blockCount + y * blocksPerAxis + x);
        if (candidate !== undefined) return candidate;
      }
    }
  }
  return undefined;
}

function connect(edges, nodes, first, second, weight) {
  void nodes;
  edges[first].set(second, Math.min(edges[first].get(second) ?? Infinity, weight));
  edges[second].set(first, Math.min(edges[second].get(first) ?? Infinity, weight));
}

function encodeGraph(nodes, edges, blocksPerAxis, blockTexels) {
  const offsets = new Uint32Array(nodes.length + 1);
  for (let node = 0; node < nodes.length; node += 1) offsets[node + 1] = offsets[node] + edges[node].size;
  const targets = new Uint32Array(offsets.at(-1));
  const weights = new Float32Array(offsets.at(-1));
  for (let node = 0; node < nodes.length; node += 1) {
    let output = offsets[node];
    for (const [target, weight] of [...edges[node]].sort(([left], [right]) => left - right)) {
      targets[output] = target; weights[output] = weight; output += 1;
    }
  }
  return {
    nodeCount: nodes.length,
    nodes: nodes.map(({ chartId, blockX, blockY, worldCenter, texelCount }) => ({ chartId, blockX, blockY, worldCenter, texelCount })),
    offsets,
    targets,
    weights,
    blocksPerAxis,
    blockTexels,
  };
}

function distance3(a, b) { return Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]); }
function clamp(value, minimum, maximum) { return Math.max(minimum, Math.min(maximum, value)); }

export function quantizeFloat16(values) {
  const encoded = new Uint16Array(values.length);
  for (let index = 0; index < values.length; index += 1) encoded[index] = float32ToFloat16(values[index]);
  return encoded;
}

export function measureFloat16WorldError(worldPos, ownership, smallestKernelWorld) {
  let worstPositionError = 0;
  let worstTexelIndex = 0;
  for (let texelIndex = 0; texelIndex < ownership.length; texelIndex += 1) {
    if (!ownership[texelIndex]) continue;
    let squaredError = 0;
    for (let axis = 0; axis < 3; axis += 1) {
      const value = worldPos[texelIndex * 3 + axis];
      const restored = float16ToFloat32(float32ToFloat16(value));
      squaredError += (restored - value) ** 2;
    }
    const error = Math.sqrt(squaredError);
    if (error > worstPositionError) { worstPositionError = error; worstTexelIndex = texelIndex; }
  }
  const threshold = smallestKernelWorld / 8;
  return {
    worstPositionError,
    worstTexelIndex,
    smallestKernelWorld,
    threshold,
    storage: worstPositionError < threshold ? 'f16' : 'f32',
  };
}

export function float32ToFloat16(value) {
  FLOAT32_VIEW[0] = value;
  const bits = UINT32_VIEW[0];
  const sign = (bits >>> 16) & 0x8000;
  let exponent = (bits >>> 23) & 0xff;
  let mantissa = bits & 0x7fffff;
  if (exponent === 0xff) return sign | (mantissa ? 0x7e00 : 0x7c00);
  exponent -= 127;
  if (exponent > 15) return sign | 0x7c00;
  if (exponent < -14) {
    if (exponent < -24) return sign;
    mantissa = (mantissa | 0x800000) >>> (-exponent - 14);
    return sign | ((mantissa + 0x1000) >>> 13);
  }
  const rounded = mantissa + 0x1000;
  if (rounded & 0x800000) {
    exponent += 1;
    mantissa = 0;
    if (exponent > 15) return sign | 0x7c00;
  } else mantissa = rounded;
  return sign | ((exponent + 15) << 10) | ((mantissa >>> 13) & 0x3ff);
}

export function float16ToFloat32(value) {
  const sign = (value & 0x8000) << 16;
  let exponent = (value >>> 10) & 0x1f;
  let mantissa = value & 0x3ff;
  let bits;
  if (exponent === 0) {
    if (mantissa === 0) bits = sign;
    else {
      exponent = -14;
      while ((mantissa & 0x400) === 0) { mantissa <<= 1; exponent -= 1; }
      mantissa &= 0x3ff;
      bits = sign | ((exponent + 127) << 23) | (mantissa << 13);
    }
  } else if (exponent === 0x1f) bits = sign | 0x7f800000 | (mantissa << 13);
  else bits = sign | ((exponent - 15 + 127) << 23) | (mantissa << 13);
  UINT32_VIEW[0] = bits >>> 0;
  return FLOAT32_VIEW[0];
}

const CONVERSION_BUFFER = new ArrayBuffer(4);
const FLOAT32_VIEW = new Float32Array(CONVERSION_BUFFER);
const UINT32_VIEW = new Uint32Array(CONVERSION_BUFFER);
import { MIN_CHART_TEXELS } from './atlas-constants.mjs';

// Packing uses closed triangle/square intersection. A center-only raster would understate the
// exact clearance needed by triangles that merely clip the edge of a texel.
export function buildChartMasks(splitMesh, target) {
  const masks = splitMesh.charts.map((chart) => buildOneChartMask(splitMesh, chart, target));
  const authoritativeTexelCount = masks.reduce((sum, mask) => sum + mask.authoritativeCount, 0);
  const dilatedTexelDemand = masks.reduce((sum, mask) => sum + mask.dilatedCount, 0);
  const totalWorldArea = splitMesh.charts.reduce((sum, chart) => sum + chart.worldArea, 0);
  const meanWorldAreaPerTexel = totalWorldArea / authoritativeTexelCount;
  for (const mask of masks) {
    mask.worldAreaPerTexel = mask.chart.worldArea / mask.authoritativeCount;
    mask.texelDensityFactor = mask.worldAreaPerTexel / meanWorldAreaPerTexel;
  }
  return {
    masks,
    authoritativeTexelCount,
    dilatedTexelDemand,
    measuredDemandRatio: dilatedTexelDemand / (target.fieldSize ** 2),
    meanWorldAreaPerTexel,
    minChartUpscaleCount: masks.filter((mask) => mask.minChartUpscaled).length,
  };
}

export function rasterizeTriangleMask(points, width, height) {
  const mask = new Uint8Array(width * height);
  const minX = Math.max(0, Math.floor(Math.min(...points.map((point) => point[0]))) - 1);
  const maxX = Math.min(width - 1, Math.floor(Math.max(...points.map((point) => point[0]))));
  const minY = Math.max(0, Math.floor(Math.min(...points.map((point) => point[1]))) - 1);
  const maxY = Math.min(height - 1, Math.floor(Math.max(...points.map((point) => point[1]))));
  for (let y = minY; y <= maxY; y += 1) {
    for (let x = minX; x <= maxX; x += 1) {
      if (triangleTouchesSquare(points, x, y)) mask[y * width + x] = 1;
    }
  }
  return mask;
}

export function dilateChebyshev(source, width, height, radius) {
  const horizontal = new Uint8Array(source.length);
  const output = new Uint8Array(source.length);
  for (let y = 0; y < height; y += 1) {
    let count = 0;
    for (let sampleX = 0; sampleX <= Math.min(width - 1, radius); sampleX += 1) {
      count += source[y * width + sampleX];
    }
    for (let x = 0; x < width; x += 1) {
      horizontal[y * width + x] = count > 0 ? 1 : 0;
      if (x + radius + 1 < width) count += source[y * width + x + radius + 1];
      if (x - radius >= 0) count -= source[y * width + x - radius];
    }
  }
  for (let x = 0; x < width; x += 1) {
    let count = 0;
    for (let sampleY = 0; sampleY <= Math.min(height - 1, radius); sampleY += 1) {
      count += horizontal[sampleY * width + x];
    }
    for (let y = 0; y < height; y += 1) {
      output[y * width + x] = count > 0 ? 1 : 0;
      if (y + radius + 1 < height) count += horizontal[(y + radius + 1) * width + x];
      if (y - radius >= 0) count -= horizontal[(y - radius) * width + x];
    }
  }
  return output;
}

export function maskIntervals(mask, width, height) {
  const rows = Array.from({ length: height }, () => []);
  for (let y = 0; y < height; y += 1) {
    let start = -1;
    for (let x = 0; x <= width; x += 1) {
      const occupied = x < width && mask[y * width + x] !== 0;
      if (occupied && start < 0) start = x;
      if (!occupied && start >= 0) {
        rows[y].push([start, x - 1]);
        start = -1;
      }
    }
  }
  return rows;
}

function buildOneChartMask(splitMesh, chart, target) {
  let chartScale = target.densityScale;
  let raster;
  let minChartUpscaled = false;
  for (let attempt = 0; attempt < 8; attempt += 1) {
    raster = rasterChart(splitMesh, chart, target, chartScale);
    const [footprintWidth, footprintHeight] = occupiedExtents(raster.authoritative, raster.width, raster.height);
    if (footprintWidth >= MIN_CHART_TEXELS && footprintHeight >= MIN_CHART_TEXELS) break;
    minChartUpscaled = true;
    chartScale *= Math.max(
      MIN_CHART_TEXELS / Math.max(footprintWidth, 1),
      MIN_CHART_TEXELS / Math.max(footprintHeight, 1),
    ) * 1.01;
  }
  const [footprintWidth, footprintHeight] = occupiedExtents(raster.authoritative, raster.width, raster.height);
  if (footprintWidth < MIN_CHART_TEXELS || footprintHeight < MIN_CHART_TEXELS) {
    throw new Error(`repack: chart ${chart.id} cannot reach the minimum footprint`);
  }
  const dilated = dilateChebyshev(
    raster.authoritative,
    raster.width,
    raster.height,
    target.gutterTexels,
  );
  const authoritativeCount = countMask(raster.authoritative);
  const dilatedCount = countMask(dilated);
  return {
    chart,
    chartScale,
    minChartUpscaled,
    ...raster,
    authoritativeCount,
    dilated,
    dilatedCount,
    authoritativeRows: maskIntervals(raster.authoritative, raster.width, raster.height),
    dilatedRows: maskIntervals(dilated, raster.width, raster.height),
  };
}

function rasterChart(splitMesh, chart, target, chartScale) {
  const scaledBounds = chart.uvBounds.map((value) => value * target.fieldSize * chartScale);
  const baseTexelX = Math.floor(scaledBounds[0]) - target.gutterTexels - 1;
  const baseTexelY = Math.floor(scaledBounds[1]) - target.gutterTexels - 1;
  const width = Math.ceil(scaledBounds[2]) - baseTexelX + target.gutterTexels + 1;
  const height = Math.ceil(scaledBounds[3]) - baseTexelY + target.gutterTexels + 1;
  const authoritative = new Uint8Array(width * height);
  const triangleRefs = new Int32Array(width * height).fill(-1);
  for (const triangleIndex of chart.triangles) {
    const points = [0, 1, 2].map((corner) => {
      const vertex = splitMesh.indices[triangleIndex * 3 + corner];
      return [
        splitMesh.uv0[vertex * 2] * target.fieldSize * chartScale - baseTexelX,
        splitMesh.uv0[vertex * 2 + 1] * target.fieldSize * chartScale - baseTexelY,
      ];
    });
    const minX = Math.max(0, Math.floor(Math.min(...points.map((point) => point[0]))) - 1);
    const maxX = Math.min(width - 1, Math.floor(Math.max(...points.map((point) => point[0]))));
    const minY = Math.max(0, Math.floor(Math.min(...points.map((point) => point[1]))) - 1);
    const maxY = Math.min(height - 1, Math.floor(Math.max(...points.map((point) => point[1]))));
    for (let y = minY; y <= maxY; y += 1) {
      for (let x = minX; x <= maxX; x += 1) {
        if (!triangleTouchesSquare(points, x, y)) continue;
        const index = y * width + x;
        authoritative[index] = 1;
        if (triangleRefs[index] < 0 || triangleIndex < triangleRefs[index]) triangleRefs[index] = triangleIndex;
      }
    }
  }
  return { width, height, baseTexelX, baseTexelY, authoritative, triangleRefs };
}

function triangleTouchesSquare(triangle, squareX, squareY) {
  const square = [
    [squareX, squareY], [squareX + 1, squareY],
    [squareX + 1, squareY + 1], [squareX, squareY + 1],
  ];
  if (triangle.some(([x, y]) => x >= squareX && x <= squareX + 1 && y >= squareY && y <= squareY + 1)) return true;
  if (square.some((point) => pointInTriangle(point, triangle))) return true;
  for (let triangleEdge = 0; triangleEdge < 3; triangleEdge += 1) {
    for (let squareEdge = 0; squareEdge < 4; squareEdge += 1) {
      if (segmentsIntersect(
        triangle[triangleEdge], triangle[(triangleEdge + 1) % 3],
        square[squareEdge], square[(squareEdge + 1) % 4],
      )) return true;
    }
  }
  return false;
}

function pointInTriangle(point, triangle) {
  const signs = [0, 1, 2].map((index) => orient(triangle[index], triangle[(index + 1) % 3], point));
  return signs.every((value) => value >= -1e-10) || signs.every((value) => value <= 1e-10);
}

function segmentsIntersect(a, b, c, d) {
  const abC = orient(a, b, c); const abD = orient(a, b, d);
  const cdA = orient(c, d, a); const cdB = orient(c, d, b);
  return Math.min(abC, abD) <= 1e-10 && Math.max(abC, abD) >= -1e-10
    && Math.min(cdA, cdB) <= 1e-10 && Math.max(cdA, cdB) >= -1e-10
    && Math.max(Math.min(a[0], b[0]), Math.min(c[0], d[0])) <= Math.min(Math.max(a[0], b[0]), Math.max(c[0], d[0])) + 1e-10
    && Math.max(Math.min(a[1], b[1]), Math.min(c[1], d[1])) <= Math.min(Math.max(a[1], b[1]), Math.max(c[1], d[1])) + 1e-10;
}

function orient(a, b, c) { return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]); }

function occupiedExtents(mask, width, height) {
  let minX = width; let minY = height; let maxX = -1; let maxY = -1;
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      if (!mask[y * width + x]) continue;
      minX = Math.min(minX, x); minY = Math.min(minY, y);
      maxX = Math.max(maxX, x); maxY = Math.max(maxY, y);
    }
  }
  return maxX < 0 ? [0, 0] : [maxX - minX + 1, maxY - minY + 1];
}

function countMask(mask) {
  let count = 0;
  for (const value of mask) count += value;
  return count;
}
